const $ = s => document.querySelector(s);
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const uid = () => Math.random().toString(36).slice(2, 9) + Date.now().toString(36).slice(-5);
const pad = n => String(n).padStart(2, "0");
const dISO = d => { const x = new Date(d); return x.getFullYear() + "-" + pad(x.getMonth() + 1) + "-" + pad(x.getDate()); };
const todayISO = () => dISO(new Date());
const parseD = s => new Date(s && s.length === 10 ? s + "T12:00:00" : s);
const fmtD = s => { if (!s) return "—"; const d = parseD(s); return pad(d.getDate()) + "/" + pad(d.getMonth() + 1) + "/" + d.getFullYear(); };
const fmtT = s => { const d = new Date(s); return pad(d.getHours()) + ":" + pad(d.getMinutes()); };
const fmtDT = s => fmtD(s) + " " + fmtT(s);
const addDays = (s, n) => { const d = parseD(s); d.setDate(d.getDate() + n); return dISO(d); };
const daysTo = s => Math.round((parseD(s) - parseD(todayISO())) / 864e5);
const tsAgo = (days, h = 10, m = 0) => { const d = new Date(); d.setDate(d.getDate() - days); d.setHours(h, m, 0, 0); return d.toISOString(); };
const norm = s => String(s ?? "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
const uniq = a => [...new Set(a.filter(Boolean))];
const initials = n => n.split(/\s+/).map(w => w[0]).slice(0, 2).join("").toUpperCase();

