const ic = (k, extra = "") => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extra}>${ICON[k]}</svg>`;

function placeholder(tipo) {
  const t = norm(tipo);
  let g;
  if (t.includes("gancho")) g = "<path d='M200 60v70'/><path d='M200 130c-40 0-60 30-60 60s25 55 55 55 50-20 50-45'/><path d='M180 60h40'/>";
  else if (t.includes("destorcedor")) g = "<circle cx='200' cy='100' r='26'/><rect x='178' y='126' width='44' height='60' rx='6'/><circle cx='200' cy='214' r='26'/>";
  else g = "<circle cx='200' cy='160' r='62'/><circle cx='200' cy='160' r='28'/><path d='M200 98V58M160 58h80'/>";
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 400 300'><rect width='400' height='300' fill='#E1EBEE'/><g fill='none' stroke='#003846' stroke-width='11' stroke-linecap='round' stroke-linejoin='round' opacity='.85'>${g}</g><text x='200' y='282' text-anchor='middle' font-family='Arial,sans-serif' font-size='17' fill='#586C73'>Sin fotografía</text></svg>`;
  return "data:image/svg+xml," + encodeURIComponent(svg);
}

