class ErrorApp extends Error {}
function msgError(e) {
  const m = (e && (e.message || e.error_description || e.msg)) || String(e || "");
  if (/Failed to fetch|NetworkError|Load failed/i.test(m)) return "Sin conexión con el servidor. Revisá internet e intentá de nuevo.";
  if (/JWT expired|invalid JWT|refresh_token/i.test(m)) return "La sesión venció. Volvé a ingresar.";
  if (/duplicate key.*serie/i.test(m)) return "Ya existe un activo con ese número de serie.";
  if (/check constraint/i.test(m)) return "Hay un dato con formato inválido.";
  return m;
}
async function rpc(fn, args) {
  const { data, error } = await sb.rpc(fn, args);
  if (error) throw new ErrorApp(msgError(error));
  return data;
}
async function traerTodo(tabla, select = "*", orden = null, asc = true) {
  const out = []; const paso = 1000;
  for (let desde = 0; ; desde += paso) {
    let q = sb.from(tabla).select(select).range(desde, desde + paso - 1);
    if (orden) q = q.order(orden, { ascending: asc });
    const { data, error } = await q;
    if (error) throw new ErrorApp(msgError(error));
    out.push(...data);
    if (data.length < paso) break;
  }
  return out;
}
let URLS = {}, URLS_TS = 0; // archivo → URL firmada (1 hora)
async function firmar(paths) {
  if (Date.now() - URLS_TS > 45 * 60 * 1000) { URLS = {}; URLS_TS = Date.now(); }
  const falta = paths.filter(p => p && !URLS[p]);
  for (let i = 0; i < falta.length; i += 100) {
    const lote = falta.slice(i, i + 100);
    const { data } = await sb.storage.from("evidencias").createSignedUrls(lote, 3600);
    (data || []).forEach(d => { if (d.signedUrl) URLS[d.path] = d.signedUrl; });
  }
}
async function cargarPerfil() {
  const { data: { user } } = await sb.auth.getUser();
  if (!user) { YO = null; return false; }
  const { data, error } = await sb.from("perfiles").select("id, usuario, nombre, rol, activo, debe_cambiar_clave").eq("id", user.id).maybeSingle();
  if (error || !data || !data.activo) { YO = null; return false; }
  YO = data; PERMS = (await rpc("mis_permisos")) || [];
  return true;
}
async function cargarDatos() {
  const [geo, sectores, estados, tipos, empresas, config, activos, hist, insps, fotos, docs, perfiles] = await Promise.all([
    traerTodo("v_geo"), traerTodo("sectores", "nombre, orden", "orden"), traerTodo("estados", "nombre, critico, orden", "orden"),
    traerTodo("tipos_herramienta", "nombre", "nombre"), traerTodo("empresas_inspeccion", "nombre", "nombre"), traerTodo("configuracion"),
    traerTodo("v_activos", "*", "numero_activo"), traerTodo("historial", "*", "id"), traerTodo("v_inspecciones", "*", "fecha"),
    traerTodo("fotografias", "*", "tomada_en"), traerTodo("documentos", "*", "subido_en"), traerTodo("perfiles", "id, usuario, nombre, rol, activo, debe_cambiar_clave, creado_en", "nombre")
  ]);
  const G = {};
  geo.forEach(r => { G[r.provincia] = G[r.provincia] || {}; if (r.localidad) { G[r.provincia][r.localidad] = G[r.provincia][r.localidad] || []; if (r.base) G[r.provincia][r.localidad].push(r.base); } });
  await firmar(fotos.map(f => f.archivo));
  const cfg = Object.fromEntries(config.map(c => [c.clave, c.valor]));
  S = {
    pais: "Argentina", geo: G, alertDias: +(cfg.alerta_dias || 30),
    sectores: sectores.map(s => s.nombre), estados: estados.map(e => ({ n: e.nombre, c: e.critico ? 1 : 0 })),
    tipos: tipos.map(t => t.nombre), empresas: empresas.map(e => e.nombre),
    activos: activos.map(a => ({ id: a.id, codigo: a.numero_activo, codAnt: a.codigo_anterior || "", responsable: a.responsable || "", tipo: a.tipo, marca: a.marca || "", modelo: a.modelo || "",
      serie: a.numero_serie || "", precinto: a.numero_precinto || "", medida: a.medida || "", empresa: a.empresa || "", provOrigen: a.provincia_origen,
      ub: { pais: a.pais, prov: a.provincia, loc: a.localidad, base: a.base, sector: a.sector, esp: a.ubicacion_especifica || "" },
      estado: a.estado, obs: a.observaciones || "", alta: a.fecha_alta, fotoPpal: a.foto_principal_id, baja: a.dado_de_baja, numAnulados: a.numeros_anulados || [] })),
    eventos: hist.map(h => ({ id: h.id, aid: h.activo_id, cod: h.numero_activo, ts: h.fecha_hora, user: h.usuario_nombre, rol: h.usuario_rol || "", tipo: h.operacion, campo: h.campo || "",
      ant: h.valor_anterior || "", nue: h.valor_nuevo || "", ubAnt: h.ubicacion_anterior || "", ubNue: h.ubicacion_nueva || "", estadoAnt: h.estado_anterior || "", estadoNue: h.estado_nuevo || "",
      motivo: h.motivo || "", obs: h.observacion || "" })),
    insps: insps.map(i => ({ id: i.id, aid: i.activo_id, cod: i.numero_activo, empresa: i.empresa || "", fecha: i.fecha, venc: i.fecha_vencimiento, resultado: i.resultado, cert: i.numero_certificado || "", obs: i.observaciones || "", user: i.usuario_nombre, ts: i.registrado_en })),
    fotos: fotos.map(f => ({ id: f.id, aid: f.activo_id, cod: f.numero_activo, archivo: f.archivo, src: URLS[f.archivo] || placeholder(""), tipo: f.tipo, obs: f.observacion || "", ts: f.tomada_en, user: f.usuario_nombre })),
    docs: docs.map(d => ({ id: d.id, aid: d.activo_id, cod: d.numero_activo, nombre: d.nombre_archivo, archivo: d.archivo, tipo: d.tipo, obs: d.descripcion || "", ts: d.subido_en, user: d.usuario_nombre, src: true })),
    users: perfiles
  };
}
async function recargar() { try { await cargarDatos(); } catch (e) { toast(msgError(e), true); } }
// Ejecuta una operación con indicador de progreso, recarga los datos y muestra el resultado
async function operar(fn, okMsg, despues) {
  if (UI.busy) return;
  UI.busy = true; const btn = document.querySelector("#modal-root button[type=submit], form button[type=submit]"); if (btn) { btn.disabled = true; btn.dataset.txt = btn.textContent; btn.textContent = "Guardando…"; }
  try {
    const r = await fn();
    await cargarDatos();
    closeModal();
    if (despues) despues(r); else render();
    if (okMsg) toast(typeof okMsg === "function" ? okMsg(r) : okMsg);
    return r;
  } catch (e) {
    toast(msgError(e), true);
    if (btn) { btn.disabled = false; btn.textContent = btn.dataset.txt; }
  } finally { UI.busy = false; }
}

/* ================= inspecciones ================= */
const lastInsp = aid => S.insps.filter(i => i.aid === aid).sort((x, y) => y.fecha.localeCompare(x.fecha))[0];
function inspStatus(a) {
  const i = lastInsp(a.id);
  if (!i || !i.venc) return { k: "sin", i, d: null };
  const d = daysTo(i.venc);
  if (d < 0) return { k: "vencida", i, d };
  if (d <= S.alertDias) return { k: "proxima", i, d };
  return { k: "vigente", i, d };
}
function inspBadge(a) {
  if (a.baja) return "";
  const s = inspStatus(a);
  if (s.k === "vencida") return `<span class="badge b-crit">Inspección vencida</span>`;
  if (s.k === "proxima") return `<span class="badge b-warn">Vence en ${s.d} día${s.d === 1 ? "" : "s"}</span>`;
  if (s.k === "vigente") return `<span class="badge b-outline">Inspección vigente</span>`;
  return `<span class="badge b-grey">Sin inspección</span>`;
}
function estBadge(n) {
  const e = estadoDef(n);
  const map = { "Nuevo": "b-outline", "Operativo": "b-solid", "Precintado": "b-soft", "Sin precinto": "b-grey", "En inspección": "b-dash", "En reparación": "b-grey", "Fuera de servicio": "b-crit", "Baja": "b-strike" };
  const cls = map[n] || (e.c ? "b-crit" : "b-soft");
  return `<span class="badge ${cls}">${esc(n)}</span>`;
}
const fotoPpal = a => { const f = a.fotoPpal ? S.fotos.find(x => x.id === a.fotoPpal) : S.fotos.filter(x => x.aid === a.id).sort((x, y) => y.ts.localeCompare(x.ts))[0]; return f ? f.src : placeholder(a.tipo); };

/* ================= filtros ================= */
function filtered(f = UI.f) {
  const q = norm(f.q).trim();
  return S.activos.filter(a => {
    if (!f.bajas && a.baja && f.estado !== "Baja") return false;
    if (f.prov && a.ub.prov !== f.prov) return false;
    if (f.loc && a.ub.loc !== f.loc) return false;
    if (f.base && a.ub.base !== f.base) return false;
    if (f.sector && a.ub.sector !== f.sector) return false;
    if (f.estado && a.estado !== f.estado) return false;
    if (f.tipo && a.tipo !== f.tipo) return false;
    if (f.empresa && a.empresa !== f.empresa) return false;
    if (f.insp && inspStatus(a).k !== f.insp) return false;
    if (q) {
      const hay = norm([a.codigo, a.codAnt, a.tipo, a.marca, a.modelo, a.serie, a.precinto, a.medida, a.empresa, a.ub.prov, a.ub.loc, a.ub.base, a.ub.sector, a.ub.esp, a.estado, a.obs].join(" "));
      if (!q.split(/\s+/).every(w => hay.includes(w))) return false;
    }
    return true;
  });
}
function filtersText(f) {
  const L = { q: "Búsqueda", prov: "Provincia", loc: "Localidad", base: "Base", sector: "Sector", estado: "Estado", tipo: "Tipo", empresa: "Empresa", insp: "Inspección" };
  const parts = Object.keys(L).filter(k => f[k]).map(k => `${L[k]}: ${f[k]}`);
  if (f.bajas) parts.push("Incluye bajas");
  return parts.length ? parts.join(" · ") : "Sin filtros";
}

