/* ================= CONSOLA DE USUARIOS ================= */
let CONSOLA = null; // { perms: {perfil_id: [..]}, aud: [...] }
async function cargarConsola() {
  const [pp, aud] = await Promise.all([traerTodo("perfil_permisos"), traerTodo("auditoria_usuarios", "*", "id", false)]);
  const perms = {}; pp.forEach(r => { (perms[r.perfil_id] = perms[r.perfil_id] || []).push(r.permiso); });
  CONSOLA = { perms, aud: aud.slice(0, 200) };
}
const permsDe = u => u.rol === "Administrador" ? PRESETS.Administrador : ((CONSOLA && CONSOLA.perms[u.id]) || []);
const nomPerm = k => (PERMISOS.find(p => p[0] === k) || [k, k])[1];
function viewUsers() {
  if (!can("usuarios")) {
    return `<div class="page-head"><div><h1>Usuarios</h1><p>Personas con acceso al sistema.</p></div></div>
    <div class="card"><div class="tablewrap"><table class="t"><thead><tr><th>Nombre</th><th>Usuario</th><th>Perfil</th><th>Estado</th></tr></thead><tbody>
    ${S.users.map(u => `<tr style="cursor:default"><td><b>${esc(u.nombre)}</b></td><td class="mono">${esc(u.usuario)}</td><td>${esc(u.rol)}</td><td>${u.activo ? '<span class="badge b-soft">Habilitado</span>' : '<span class="badge b-crit-o">Deshabilitado</span>'}</td></tr>`).join("")}
    </tbody></table></div></div>`;
  }
  if (!CONSOLA) { cargarConsola().then(render).catch(e => toast(msgError(e), true)); return `<div class="empty">Cargando la consola de usuarios…</div>`; }
  const activos = S.users.filter(u => u.activo).length;
  return `
  <div class="page-head"><div><h1>Consola de usuarios</h1><p>${S.users.length} usuarios · ${activos} habilitados. Cada cambio queda registrado en la auditoría.</p></div>
    <button class="btn" data-act="userNew">${ic("plus")}Nuevo usuario</button></div>
  <div class="card"><div class="tablewrap"><table class="t"><thead><tr><th>Nombre</th><th>Usuario</th><th>Perfil</th><th>Permisos</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>
  ${S.users.map(u => {
    const ps = permsDe(u);
    return `<tr style="cursor:default" class="${u.activo ? "" : "is-baja"}"><td><div class="row" style="flex-wrap:nowrap"><span class="avatar">${initials(u.nombre)}</span><b>${esc(u.nombre)}</b>${u.id === YO.id ? '<span class="badge b-soft">Vos</span>' : ""}</div></td>
    <td class="mono">${esc(u.usuario)}</td><td>${esc(u.rol)}</td>
    <td style="min-width:260px;max-width:420px">${u.rol === "Administrador" ? '<span class="muted" style="font-size:13px">Todos</span>' : ps.length ? `<div class="chips">${ps.map(k => `<span class="chip" style="padding:2px 9px;font-size:12px${k === "baja" ? ";border-color:var(--rojo);color:var(--rojo-ink)" : ""}">${esc(nomPerm(k))}</span>`).join("")}</div>` : '<span class="muted" style="font-size:13px">Solo lectura</span>'}</td>
    <td>${u.activo ? '<span class="badge b-soft">Habilitado</span>' : '<span class="badge b-crit-o">Deshabilitado</span>'}${u.debe_cambiar_clave && u.activo ? '<br><span class="muted" style="font-size:12px">Debe cambiar la contraseña</span>' : ""}</td>
    <td style="width:1%"><div class="stack" style="gap:6px;align-items:stretch;min-width:132px">
      <button class="btn ghost sm" data-act="userEdit" data-id="${u.id}">${ic("edit")}Editar</button>
      <button class="btn ghost sm" data-act="userPass" data-id="${u.id}" title="Asignar contraseña temporal">${ic("lock")}Contraseña</button>
      ${u.id !== YO.id ? `<button class="btn ${u.activo ? "danger-ghost" : "ghost"} sm" data-act="userToggle" data-id="${u.id}">${u.activo ? "Deshabilitar" : "Habilitar"}</button>` : ""}
    </div></td></tr>`; }).join("")}
  </tbody></table></div></div>
  <section class="card pad" style="margin-top:16px"><h3 style="margin-bottom:10px">Permisos sugeridos por perfil</h3>
    <p class="muted" style="margin:0 0 10px;font-size:13.5px">Al crear o editar un usuario se proponen estos permisos. Podés ajustarlos uno por uno; por ejemplo, habilitar <b>Dar de baja activos</b> a un Supervisor.</p>
    <div class="tablewrap"><table class="t"><thead><tr><th>Permiso</th>${Object.keys(ROLES).map(r => `<th>${r}</th>`).join("")}</tr></thead><tbody>
    <tr style="cursor:default"><td>Consultar activos, fichas, historial y reportes</td>${Object.keys(ROLES).map(() => "<td>Sí</td>").join("")}</tr>
    ${PERMISOS.map(([k, t]) => `<tr style="cursor:default"><td>${t}</td>${Object.keys(ROLES).map(r => `<td>${PRESETS[r].includes(k) ? "Sí" : '<span class="muted">—</span>'}</td>`).join("")}</tr>`).join("")}
    </tbody></table></div></section>
  <section class="card" style="margin-top:16px"><div class="toolbar"><h3>Auditoría de usuarios</h3><span class="muted" style="font-size:13px">Últimos ${CONSOLA.aud.length} registros · no se pueden modificar</span></div>
    ${CONSOLA.aud.length ? `<div class="tablewrap"><table class="t"><thead><tr><th>Fecha</th><th>Hora</th><th>Realizado por</th><th>Acción</th><th>Usuario</th><th>Detalle</th></tr></thead><tbody>
    ${CONSOLA.aud.map(r => `<tr style="cursor:default"><td class="mono">${fmtD(r.fecha_hora)}</td><td class="mono">${fmtT(r.fecha_hora)}</td><td>${esc(r.actor_nombre)}</td><td>${esc(r.accion)}</td><td class="mono">${esc(r.perfil_usuario || "")}</td><td style="font-size:13px">${esc(r.detalle || "")}</td></tr>`).join("")}
    </tbody></table></div>` : '<p class="empty">Sin registros.</p>'}
  </section>`;
}
