function genClave() {
  const A = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz", D = "23456789", all = A + D;
  const r = n => { const b = new Uint32Array(n); crypto.getRandomValues(b); return [...b].map(x => all[x % all.length]).join(""); };
  let c; do { c = "Clear-" + r(8); } while (!(/[0-9]/.test(c.slice(6)) && /[A-Za-z]/.test(c.slice(6)))); return c;
}
