async function consola(body) {
  const { data, error } = await sb.functions.invoke("admin-usuarios", { body });
  if (error) {
    let m = error.message;
    try { const j = await error.context.json(); if (j && j.error) m = j.error; } catch (e) {}
    throw new ErrorApp(msgError({ message: m }));
  }
  if (data && data.error) throw new ErrorApp(data.error);
  return data;
}

/* ================= archivos ================= */
function readAsDataURL(file) { return new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = rej; r.readAsDataURL(file); }); }
async function resizeImage(file, max = 1280) {
  const url = await readAsDataURL(file);
  return new Promise(res => {
    const img = new Image();
    img.onload = () => { const k = Math.min(1, max / Math.max(img.width, img.height)); const c = document.createElement("canvas"); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k); c.getContext("2d").drawImage(img, 0, 0, c.width, c.height); res(c.toDataURL("image/jpeg", .82)); };
    img.onerror = () => res(url); img.src = url;
  });
}
const MIME_DOC = ["application/pdf", "image/jpeg", "image/png", "image/webp", "image/heic", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "application/vnd.ms-excel", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "text/plain"];
function dataURLtoBlob(u) { const [h, d] = u.split(","); const bin = atob(d); const arr = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i); return new Blob([arr], { type: h.match(/data:(.*?);/)[1] }); }
async function subir(path, blob, tipo) {
  const { error } = await sb.storage.from("evidencias").upload(path, blob, { contentType: tipo, upsert: false });
  if (error) throw new ErrorApp("No se pudo subir el archivo: " + msgError(error));
}
async function addPhoto(a, file, tipo, obs, principal = false) {
  const blob = dataURLtoBlob(await resizeImage(file, 1600));
  const path = `${a.id}/foto-${crypto.randomUUID()}.jpg`;
  await subir(path, blob, "image/jpeg");
  return rpc("registrar_foto", { p_id: a.id, p_archivo: path, p_tipo: tipo, p_obs: obs || "", p_principal: !!principal });
}
async function addDoc(a, file, tipo, obs, inspeccion = null) {
  if (file.size > 20 * 1024 * 1024) throw new ErrorApp("El archivo supera los 20 MB.");
  const mime = file.type || "application/octet-stream";
  if (!MIME_DOC.includes(mime)) throw new ErrorApp("Tipo de archivo no permitido. Usá PDF, imagen, Word, Excel o texto.");
  const limpio = file.name.normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^A-Za-z0-9._-]+/g, "_").slice(-80);
  const path = `${a.id}/doc-${crypto.randomUUID()}-${limpio}`;
  await subir(path, file, mime);
  return rpc("registrar_documento", { p_id: a.id, p_archivo: path, p_nombre: file.name, p_tipo: tipo, p_desc: obs || "", p_inspeccion: inspeccion });
}

/* ================= descargas / export ================= */
async function saveFile(filename, data) {
  try {
    const blob = data instanceof Blob ? data : new Blob([data], { type: "text/plain;charset=utf-8" });
    const u = URL.createObjectURL(blob); const l = document.createElement("a"); l.href = u; l.download = filename;
    document.body.appendChild(l); l.click(); l.remove(); setTimeout(() => URL.revokeObjectURL(u), 4000);
    toast("Archivo descargado: " + filename);
  } catch (e) { toast("No se pudo descargar el archivo.", true); }
}
const stamp = () => { const d = new Date(); return dISO(d) + "_" + pad(d.getHours()) + pad(d.getMinutes()); };
function toCSV(head, body) { const q = v => { const s = String(v ?? ""); return /[";\n,]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; }; return "﻿" + [head, ...body].map(r => r.map(q).join(";")).join("\r\n"); }
function toXLSX(sheet, head, body) {
  if (!window.XLSX) { toast("No se pudo cargar el generador de Excel.", true); return null; }
  const ws = XLSX.utils.aoa_to_sheet([head, ...body]);
  ws["!cols"] = head.map((h, i) => ({ wch: Math.min(40, Math.max(h.length, ...body.map(r => String(r[i] ?? "").length)) + 2) }));
  const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, ws, sheet.slice(0, 31));
  return new Blob([XLSX.write(wb, { bookType: "xlsx", type: "array" })]);
}
function toPDF(title, filtros, head, body, cols) {
  const J = window.jspdf && window.jspdf.jsPDF;
  if (!J) { toast("No se pudo cargar el generador de PDF.", true); return null; }
  const H = cols ? cols.map(i => head[i]) : head, B = cols ? body.map(r => cols.map(i => r[i] ?? "")) : body;
  const doc = new J({ orientation: "landscape", unit: "mm", format: "a4" });
  const W = doc.internal.pageSize.getWidth(), Hh = doc.internal.pageSize.getHeight();
  const header = () => { doc.setFillColor(0, 56, 70); doc.rect(0, 0, W, 20, "F"); doc.setFillColor(213, 25, 32); doc.rect(0, 20, W, 1.2, "F"); doc.setTextColor(255, 255, 255); doc.setFont("helvetica", "bold"); doc.setFontSize(14); doc.text("Inventario y Trazabilidad", 12, 9); doc.setFont("helvetica", "normal"); doc.setFontSize(9); doc.text("Gestión de activos, herramientas y equipos", 12, 14.5); try { doc.addImage(LOGO_REV, "PNG", W - 12 - 44, 3.5, 44, 13.4); } catch (e) {} };
  header();
  doc.setTextColor(0, 56, 70); doc.setFont("helvetica", "bold"); doc.setFontSize(16); doc.text(title, 12, 32);
  doc.setFont("helvetica", "normal"); doc.setFontSize(9); doc.setTextColor(80, 96, 102);
  doc.text(`Generado: ${fmtDT(new Date().toISOString())}   ·   Usuario: ${me().nombre} (${me().rol})   ·   Registros: ${B.length}`, 12, 38);
  doc.text(doc.splitTextToSize("Filtros: " + filtros, W - 24), 12, 43);
  const estIdx = H.indexOf("Estado");
  doc.autoTable({
    head: [H], body: B.length ? B : [[{ content: "Sin registros", colSpan: H.length, styles: { halign: "center", textColor: [90, 108, 115] } }]], startY: 48, margin: { top: 28, left: 12, right: 12, bottom: 14 },
    styles: { font: "helvetica", fontSize: 8, cellPadding: 1.8, textColor: [18, 36, 41], lineColor: [215, 224, 227], lineWidth: .1 },
    headStyles: { fillColor: [0, 56, 70], textColor: 255, fontStyle: "bold" }, alternateRowStyles: { fillColor: [246, 248, 249] },
    didParseCell: d => { if (d.section === "body" && d.column.index === estIdx && estadoDef(String(d.cell.raw)).c) { d.cell.styles.textColor = [213, 25, 32]; d.cell.styles.fontStyle = "bold"; } },
    didDrawPage: () => { if (doc.internal.getNumberOfPages() > 1) header(); }
  });
  const n = doc.internal.getNumberOfPages();
  for (let p = 1; p <= n; p++) { doc.setPage(p); doc.setFontSize(8); doc.setTextColor(90, 108, 115); doc.text(`Página ${p} de ${n}`, W - 12, Hh - 7, { align: "right" }); doc.text(title, 12, Hh - 7); }
  return doc.output("blob");
}
function exportData(fmt, name, title, filtros, head, body, cols) {
  const base = name + "_" + stamp();
  if (fmt === "csv") return saveFile(base + ".csv", toCSV(head, body));
  if (fmt === "xlsx") { const b = toXLSX(title, head, body); if (b) saveFile(base + ".xlsx", b); return; }
  const b = toPDF(title, filtros, head, body, cols); if (b) saveFile(base + ".pdf", b);
}

/* ================= import ================= */
let IMP = null;
async function parseImport(file) {
  if (!window.XLSX) { $("#impprev").innerHTML = '<p class="err">No se pudo cargar el lector de Excel.</p>'; return; }
  const wb = XLSX.read(await file.arrayBuffer(), { type: "array" });
  const ws = wb.Sheets[wb.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json(ws, { defval: "", raw: false });
  const key = h => norm(h).replace(/[^a-z0-9]/g, "");
  const MAP = { codigo: "cod", herramienta: "tipo", empresainspeccion: "empresa", nprecinto: "precinto", precinto: "precinto", medida: "medida", marca: "marca", equipobase: "base", ubicacion: "loc", estado: "estado", observacion: "obs", observaciones: "obs" };
  const recs = rows.map(r => { const o = {}; Object.keys(r).forEach(h => { const k = MAP[key(h)]; if (k) o[k] = String(r[h]).trim(); }); return o; }).filter(o => o.cod || o.tipo);
  const dup = recs.filter(o => o.cod && byCode(o.cod));
  IMP = recs.filter(o => !(o.cod && byCode(o.cod)));
  $("#impprev").innerHTML = recs.length ? `<div class="insp-state"><div class="big">${IMP.length}</div><div><b>filas nuevas para importar</b><br><span class="muted">${recs.length} leídas · ${dup.length} ya existen y se omitirán</span></div></div>` : '<p class="err">No se encontraron columnas reconocibles (Codigo, Herramienta…).</p>';
  $("#impgo").disabled = !IMP.length;
}
async function doImport() {
  const prov = $("#improv").value;
  const filas = IMP.map(o => ({ cod: o.cod || "", tipo: o.tipo || "", empresa: o.empresa || "", precinto: o.precinto || "", medida: o.medida || "", marca: o.marca || "", base: o.base || "", loc: o.loc || "", estado: o.estado || "", obs: o.obs || "" }));
  await operar(() => rpc("importar_activos", { p_filas: filas, p_prov: prov }), r => `${r.importados} activos importados${r.omitidos ? ` · ${r.omitidos} omitidos` : ""}.`, () => { IMP = null; go("inventario"); });
}

/* ================= QR: lectura desde foto ================= */
async function scanImage(file) {
  const msg = $("#scanmsg"); msg.textContent = "Leyendo la imagen…";
  if (!window.jsQR) { msg.textContent = "No se pudo cargar el lector de QR. Ingresá el código a mano."; return; }
  const url = await readAsDataURL(file);
  const img = new Image();
  img.onload = () => {
    let code = null;
    for (const max of [1200, 800, 500]) {
      const k = Math.min(1, max / Math.max(img.width, img.height)); const c = document.createElement("canvas"); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
      const ctx = c.getContext("2d"); ctx.drawImage(img, 0, 0, c.width, c.height);
      const r = jsQR(ctx.getImageData(0, 0, c.width, c.height).data, c.width, c.height); if (r) { code = r.data; break; }
    }
    if (!code) { msg.textContent = "No se detectó un QR. Probá con más luz o más cerca, o ingresá el código."; return; }
    const m = code.match(/ACT-\d{6}/i); const a = m ? byCode(m[0]) : byCode(code);
    if (a) go("ficha", a.id); else msg.textContent = `El QR dice "${code}", pero no corresponde a ningún activo.`;
  };
  img.src = url;
}

/* ================= toast ================= */
let tT;
function toast(m, crit) { let t = $("#toast"); if (!t) { t = document.createElement("div"); t.id = "toast"; t.setAttribute("role", "status"); document.body.appendChild(t); } t.className = "toast" + (crit ? " crit" : ""); t.textContent = m; t.hidden = false; clearTimeout(tT); tT = setTimeout(() => t.hidden = true, 3800); }

/* ================= eventos ================= */
document.addEventListener("click", async e => {
  const t = e.target;
  const ov = t.closest("[data-act='closeOv']"); if (ov && t === ov) { closeModal(); return; }
  const g = t.closest("[data-go]"); if (g) { if (g.disabled) return; closeModal(); go(g.dataset.go); return; }
  const o = t.closest("[data-open]"); if (o) { closeModal(); go("ficha", o.dataset.open); return; }
  const b = t.closest("[data-act]"); if (!b) return;
  const act = b.dataset.act, id = b.dataset.id, a = id ? asset(id) : null;
  switch (act) {
    case "logout": await salir(); break;
    case "miClave": modal("Cambiar mi contraseña", viewCambioClave(false)); break;
    case "userMenu": modal("Mi cuenta", `<div class="stack"><div class="row"><span class="avatar">${initials(YO.nombre)}</span><div><b>${esc(YO.nombre)}</b><br><span class="muted">${esc(YO.rol)} · <span class="mono">${esc(YO.usuario)}</span></span></div></div>
      <div><span class="lbl">Tus permisos</span><div class="chips" style="margin-top:6px">${PERMS.length ? PERMS.map(k => `<span class="chip" style="font-size:12px;padding:2px 9px">${esc(nomPerm(k))}</span>`).join("") : '<span class="muted">Solo lectura</span>'}</div></div></div>`,
      `<button class="btn ghost" data-act="miClave">Cambiar mi contraseña</button><button class="btn" data-act="logout">Salir</button>`); break;
    case "userNew": userNewModal(); break;
    case "userEdit": userEditModal(S.users.find(u => u.id === id)); break;
    case "userPass": userPassModal(S.users.find(u => u.id === id)); break;
    case "userToggle": { const u = S.users.find(x => x.id === id);
      if (u.activo) { formModal("Deshabilitar usuario", `<p class="full" style="margin:0"><b>${esc(u.nombre)}</b> (<span class="mono">${esc(u.usuario)}</span>) no podrá ingresar ni operar. Sus registros en el historial se conservan. Podés volver a habilitarlo cuando quieras.</p>`, `data-form="userToggle" data-id="${u.id}" data-v="0"`, "Deshabilitar", true); }
      else await operar(async () => { await consola({ accion: "actualizar", id: u.id, activo: true }); await cargarConsola(); }, `${u.nombre} habilitado.`);
      break; }
    case "genPass": { const el = document.getElementById(b.dataset.t); if (el) el.value = genClave(); break; }
    case "copyPass": { const el = document.getElementById(b.dataset.t); try { await navigator.clipboard.writeText(el.value); toast("Contraseña copiada."); } catch (err) { el.select(); } break; }
    case "permPreset": { const rol = $("#m_ur").value; document.querySelectorAll("input[name=perm]").forEach(c => { if (!c.disabled || rol === "Administrador") c.checked = PRESETS[rol].includes(c.value); }); break; }
    case "drawer": UI.drawer = !UI.drawer; render(); break;
    case "close": closeModal(); break;
    case "copyNew": try { await navigator.clipboard.writeText(UI.nuevo || ""); toast("Datos copiados."); } catch (err) { toast("Seleccioná y copiá los datos manualmente."); } break;
    case "jump": document.getElementById(id)?.scrollIntoView({ behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block: "start" }); break;
    case "filterGo": UI.f = blankFilters(); if (b.dataset.k) UI.f[b.dataset.k] = b.dataset.v; go("inventario"); break;
    case "clearF": UI.f = blankFilters(); render(); break;
    case "goInv": go("inventario"); break;
    case "openAsset": go("ficha", id); break;
    case "editGo": go("editar", id); break;
    case "moveModal": moveModal(a); break;
    case "estadoModal": estadoModal(a); break;
    case "inspModal": inspModal(a); break;
    case "inspPick": inspModal(null, true); break;
    case "fotoModal": fotoModal(a); break;
    case "fotoPick": fotoModal(null, true); break;
    case "docModal": docModal(a); break;
    case "docPick": docModal(null, true); break;
    case "obsModal": obsModal(a); break;
    case "bajaModal": bajaModal(a); break;
    case "reingreso": reingresoModal(a); break;
    case "qrModal": qrModal(a); break;
    case "corrModal": if (can("corregir_numero")) corrModal(a); break;
    case "heroZoom": { const f = a.fotoPpal ? S.fotos.find(x => x.id === a.fotoPpal) : S.fotos.filter(x => x.aid === a.id).sort((x, y) => y.ts.localeCompare(x.ts))[0]; if (f) lightbox(f); else if (can("foto")) fotoModal(a); break; }
    case "lightbox": lightbox(S.fotos.find(f => f.id === id)); break;
    case "setPpal": await operar(() => rpc("fijar_foto_principal", { p_foto: id }), "Fotografía principal actualizada. La anterior sigue en la galería."); break;
    case "docDl": { const d = S.docs.find(x => x.id === id); const { data, error } = await sb.storage.from("evidencias").download(d.archivo); if (error) toast(msgError(error), true); else saveFile(d.nombre, data); break; }
    case "qrDl": qrDownload(a); break;
    case "export": { const list = filtered(); exportData(b.dataset.fmt, "inventario", "Inventario" + (filtersText(UI.f) === "Sin filtros" ? " completo" : " filtrado"), filtersText(UI.f), INV_HEAD, list.map(invRow), PDF_INV); break; }
    case "exportMov": { const r = buildReport("mov"); exportData(b.dataset.fmt, "movimientos", r.title, UI.movF.tipo ? "Operación: " + UI.movF.tipo : "Sin filtros", r.head, r.body); break; }
    case "rep": { const r = buildReport(b.dataset.k); exportData(b.dataset.fmt, "reporte_" + b.dataset.k, r.title, r.filtros, r.head, r.body, b.dataset.fmt === "pdf" ? r.pdfCols : null); break; }
    case "importModal": importModal(); break;
    case "importGo": doImport(); break;
    case "geoAdd": geoAddModal(b.dataset.lvl, JSON.parse(b.dataset.path)); break;
  }
});

async function qrDownload(a) {
  const src = $("#qrc canvas") || $("#qrc img"); if (!src) return;
  const c = document.createElement("canvas"); c.width = 900; c.height = 420; const x = c.getContext("2d");
  x.fillStyle = "#fff"; x.fillRect(0, 0, 900, 420); x.strokeStyle = "#003846"; x.lineWidth = 8; x.strokeRect(4, 4, 892, 412);
  x.drawImage(src, 30, 30, 360, 360); x.fillStyle = "#003846"; x.fillRect(418, 30, 4, 360);
  x.fillStyle = "#586C73"; x.font = "600 22px Arial"; x.fillText("ACTIVO", 450, 90);
  x.fillStyle = "#003846"; x.font = "bold 58px 'IBM Plex Mono', monospace"; x.fillText(a.codigo, 450, 160);
  x.font = "600 36px 'Barlow Condensed', Arial"; x.fillText(a.tipo.slice(0, 28), 450, 215);
  if (a.medida) { x.font = "28px Arial"; x.fillText(a.medida, 450, 258); }
  x.fillStyle = "#D51920"; x.fillRect(450, 300, 90, 10);
  await new Promise(res => { const li = new Image(); li.onload = () => { x.drawImage(li, 450, 326, 200, 200 * li.height / li.width); res(); }; li.onerror = res; li.src = LOGO; });
  c.toBlob(bl => saveFile("QR_" + a.codigo + ".png", bl), "image/png");
}

document.addEventListener("submit", async e => {
  const f = e.target; const kind = f.dataset.form; if (!kind) return;
  e.preventDefault();
  const fd = new FormData(f); const v = k => String(fd.get(k) ?? "").trim();
  const id = f.dataset.id || v("aid"); const a = id ? asset(id) : null;
  const need = (k, msg = "Completá este campo.") => { if (!v(k)) { const el = f.querySelector("#merr_" + k) || f.querySelector("#err_" + k); if (el) el.textContent = msg; f.querySelector(`[name="${k}"]`)?.focus(); return false; } return true; };
  const errU = m => { const el = f.querySelector("#merr_u"); if (el) el.textContent = m; else toast(m, true); };
  switch (kind) {
    case "login": return ingresar(f, v("usuario"), fd.get("clave"));
    case "clave": {
      const c1 = String(fd.get("c1") || ""), c2 = String(fd.get("c2") || ""), er = f.querySelector("#cerr");
      if (!claveValida(c1)) { er.textContent = "La contraseña debe tener al menos 8 caracteres, con letras y números."; return; }
      if (c1 !== c2) { er.textContent = "Las contraseñas no coinciden."; return; }
      const btn = f.querySelector("button[type=submit]"); btn.disabled = true;
      const { error } = await sb.auth.updateUser({ password: c1 });
      if (error) { btn.disabled = false; er.textContent = /different|same/i.test(error.message) ? "La nueva contraseña debe ser distinta de la anterior." : msgError(error); return; }
      await rpc("marcar_clave_cambiada").catch(() => {});
      YO.debe_cambiar_clave = false; closeModal();
      if (!S) await iniciarSesion(); else render();
      toast("Contraseña actualizada."); break;
    }
    case "gsearch": case "hsearch": UI.f = blankFilters(); UI.f.q = (kind === "gsearch" ? $("#gq") : $("#hq")).value; go("inventario"); break;
    case "codeGo": { const x = byCode(v("c")); if (x) go("ficha", x.id); else $("#codemsg").textContent = "No existe un activo con ese código."; break; }
    case "move": {
      if (!need("motivo")) return;
      await operar(() => rpc("mover_activo", { p_id: a.id, p_prov: v("prov"), p_loc: v("loc"), p_base: v("base"), p_sector: v("sector"), p_esp: v("esp"), p_motivo: v("motivo"), p_obs: v("obs") }),
        "Movimiento registrado. El número sigue siendo " + a.codigo + "."); break;
    }
    case "estado": {
      if (!need("motivo")) return;
      const ant = a.estado;
      await operar(() => rpc("cambiar_estado", { p_id: a.id, p_estado: v("estado"), p_motivo: v("motivo"), p_obs: v("obs") }), `Estado: ${ant} → ${v("estado")}`); break;
    }
    case "insp": {
      if (!a) return; if (!need("empresa")) return;
      if (!v("fecha") || !v("venc")) return toast("Completá fecha y vencimiento.", true);
      await operar(async () => {
        const inspId = await rpc("registrar_inspeccion", { p_id: a.id, p_empresa: v("empresa"), p_fecha: v("fecha"), p_venc: v("venc"), p_resultado: v("resultado"), p_cert: v("cert"), p_precinto: v("precinto"), p_obs: v("obs") });
        for (const file of fd.getAll("fotos").filter(x => x && x.size)) await addPhoto(a, file, "Inspección", "Inspección " + fmtD(v("fecha")));
        const pdf = fd.get("pdf"); if (pdf && pdf.size) await addDoc(a, pdf, "Certificado", "Inspección " + fmtD(v("fecha")), inspId);
      }, "Inspección registrada."); break;
    }
    case "foto": {
      if (!a) return;
      const file = [fd.get("cam"), fd.get("file")].find(x => x && x.size);
      if (!file) { f.querySelector("#merr_file").textContent = "Tomá o elegí una fotografía."; return; }
      await operar(() => addPhoto(a, file, v("tipo"), v("obs"), !!fd.get("ppal")), "Fotografía guardada en la galería histórica."); break;
    }
    case "doc": {
      if (!a) return; const file = fd.get("file");
      if (!file || !file.size) { f.querySelector("#merr_file").textContent = "Elegí un archivo."; return; }
      await operar(() => addDoc(a, file, v("tipo"), v("obs")), "Documento adjuntado."); break;
    }
    case "obs": {
      if (!need("obs")) return;
      await operar(() => rpc("registrar_novedad", { p_id: a.id, p_tipo: v("tipo"), p_detalle: v("obs") }), "Novedad registrada."); break;
    }
    case "baja": {
      if (!need("motivo", "El motivo es obligatorio para dar de baja.")) return;
      await operar(() => rpc("dar_baja", { p_id: a.id, p_motivo: v("motivo"), p_obs: v("obs") }), a.codigo + " dado de baja. Su historial se conserva."); break;
    }
    case "reingreso": {
      if (!need("motivo")) return;
      await operar(() => rpc("reingresar", { p_id: a.id, p_estado: v("estado"), p_motivo: v("motivo"), p_obs: v("obs") }), "Reingreso registrado."); break;
    }
    case "corr": {
      if (!need("motivo")) return; if (!need("aut")) return;
      if (v("conf").toUpperCase() !== a.codigo) { f.querySelector("#merr_conf").textContent = "El número no coincide."; return; }
      const old = a.codigo;
      await operar(() => rpc("corregir_numero", { p_id: a.id, p_motivo: v("motivo"), p_autorizacion: v("aut"), p_confirmacion: v("conf") }), nuevo => `${old} anulado. Nuevo número: ${nuevo}. Reimprimí la etiqueta QR.`); break;
    }
    case "asset": return submitAsset(f, fd, v);
    case "geo": {
      const n = v("n"); if (!n) return; const lvl = f.dataset.lvl, p = JSON.parse(f.dataset.path);
      const tipo = { prov: "provincia", loc: "localidad", base: "base", sector: "sector" }[lvl];
      await operar(() => rpc("agregar_catalogo", { p_tipo: tipo, p_nombre: n, p_prov: p[0] || null, p_loc: p[1] || null, p_critico: false }), "Agregado al catálogo."); break;
    }
    case "estadoAdd": { const n = v("n"); if (n) await operar(() => rpc("agregar_catalogo", { p_tipo: "estado", p_nombre: n, p_prov: null, p_loc: null, p_critico: !!fd.get("c") }), "Estado agregado."); break; }
    case "tipoAdd": { const n = v("n"); if (n) await operar(() => rpc("agregar_catalogo", { p_tipo: "tipo", p_nombre: n, p_prov: null, p_loc: null, p_critico: false }), "Tipo agregado."); break; }
    case "empAdd": { const n = v("n"); if (n) await operar(() => rpc("agregar_catalogo", { p_tipo: "empresa", p_nombre: n, p_prov: null, p_loc: null, p_critico: false }), "Empresa agregada."); break; }
    case "alertCfg": { const d = Math.max(1, Math.min(365, +v("d") || 30)); await operar(() => rpc("configurar", { p_clave: "alerta_dias", p_valor: String(d) }), "Alertas: " + d + " días de anticipación."); break; }
    // ---- consola de usuarios ----
    case "userNew": {
      const perms = fd.getAll("perm");
      if (!v("nombre")) return errU("El nombre es obligatorio.");
      if (!/^[a-z0-9._-]{3,40}$/.test(v("usuario").toLowerCase())) return errU("El usuario debe tener entre 3 y 40 caracteres: minúsculas, números, punto, guion o guion bajo.");
      if (!claveValida(v("clave"))) return errU("La contraseña debe tener al menos 8 caracteres, con letras y números.");
      const clave = v("clave"), usuario = v("usuario").toLowerCase();
      await operar(async () => { await consola({ accion: "crear", usuario, nombre: v("nombre"), rol: v("rol"), clave, permisos: perms }); await cargarConsola(); },
        null, () => { render(); modal("Usuario creado", `<div class="stack"><p style="margin:0">Pasale estos datos a <b>${esc(v("nombre"))}</b> por un canal privado. Al ingresar deberá elegir su propia contraseña.</p>
          <dl class="kv"><div><dt>Usuario</dt><dd class="mono">${esc(usuario)}</dd></div><div><dt>Contraseña inicial</dt><dd class="mono" id="nuevaClave">${esc(clave)}</dd></div></dl></div>`,
          `<button class="btn ghost" data-act="copyNew">Copiar datos</button><button class="btn" data-act="close">Listo</button>`); UI.nuevo = `Usuario: ${usuario}\nContraseña inicial: ${clave}`; });
      break;
    }
    case "userEdit": {
      const u = S.users.find(x => x.id === id); const body = { accion: "actualizar", id, nombre: v("nombre"), permisos: fd.getAll("perm") };
      if (fd.get("rol") && fd.get("rol") !== u.rol) body.rol = v("rol");
      await operar(async () => { const r = await consola(body); await cargarConsola(); return r; }, r => r.cambios && r.cambios.length ? "Cambios guardados." : "Sin cambios.");
      if (u.id === YO.id) await cargarPerfil().then(render);
      break;
    }
    case "userPass": {
      if (!claveValida(v("clave"))) return errU("La contraseña debe tener al menos 8 caracteres, con letras y números.");
      await operar(async () => { await consola({ accion: "clave", id, clave: v("clave") }); await cargarConsola(); }, "Contraseña asignada."); break;
    }
    case "userToggle": {
      const u = S.users.find(x => x.id === id);
      await operar(async () => { await consola({ accion: "actualizar", id, activo: f.dataset.v === "1" }); await cargarConsola(); }, `${u.nombre} ${f.dataset.v === "1" ? "habilitado" : "deshabilitado"}.`); break;
    }
  }
});

async function submitAsset(f, fd, v) {
  f.querySelectorAll(".err").forEach(e => e.textContent = "");
  const editId = f.dataset.id; const a = editId ? asset(editId) : null;
  if (!v("tipo")) { $("#err_tipo").textContent = "Indicá el tipo de herramienta."; $("#f_tipo").focus(); return; }
  if (v("serie") && S.activos.some(x => x.serie && x.serie === v("serie") && x !== a)) { $("#err_serie").textContent = "Ya existe un activo con ese número de serie."; $("#f_serie").focus(); return; }
  if (a) {
    const campos = {}; ["responsable", "tipo", "marca", "modelo", "serie", "precinto", "medida", "empresa", "obs"].forEach(k => { campos[k] = v(k); });
    await operar(() => rpc("editar_activo", { p_id: a.id, p: campos, p_motivo: v("motivo") }), n => n ? `${n} campo${n > 1 ? "s" : ""} modificado${n > 1 ? "s" : ""}, con historial.` : "Sin cambios.", () => go("ficha", a.id));
    return;
  }
  const datos = { responsable: v("responsable"), tipo: v("tipo"), marca: v("marca"), modelo: v("modelo"), serie: v("serie"), precinto: v("precinto"), medida: v("medida"), empresa: v("empresa"),
    prov: v("prov"), loc: v("loc"), base: v("base"), sector: v("sector"), esp: v("esp"), estado: v("estado"), obs: v("obs"), alta: v("alta"),
    insp_fecha: v("fInsp"), insp_venc: v("fVenc") || (v("fInsp") ? addDays(v("fInsp"), 365) : ""), insp_cert: v("cert") };
  await operar(async () => {
    const r = await rpc("alta_activo", { p: datos });
    const na = { id: r.id, codigo: r.numero_activo };
    const pp = fd.get("ppal"); if (pp && pp.size) await addPhoto(na, pp, "Estado general", "Foto principal de alta", true);
    for (const file of fd.getAll("fotos").filter(x => x && x.size)) await addPhoto(na, file, "Estado general", "");
    for (const file of fd.getAll("docs").filter(x => x && x.size)) await addDoc(na, file, "Otro", "Adjunto en el alta");
    return r;
  }, r => r.numero_activo + " dado de alta.", r => go("ficha", r.id));
}

/* ================= sesión ================= */
async function ingresar(f, usuario, clave) {
  const er = f.querySelector("#lerr"), btn = f.querySelector("button[type=submit]");
  usuario = String(usuario || "").trim().toLowerCase();
  if (!usuario || !clave) { er.textContent = "Ingresá usuario y contraseña."; return; }
  btn.disabled = true; btn.textContent = "Ingresando…"; er.textContent = "";
  const email = usuario.includes("@") ? usuario : `${usuario}@${DOMINIO}`;
  const { error } = await sb.auth.signInWithPassword({ email, password: String(clave) });
  if (error) {
    btn.disabled = false; btn.textContent = "Ingresar";
    er.textContent = /banned/i.test(error.message) ? "Tu usuario está deshabilitado. Consultá al administrador." : /invalid/i.test(error.message) ? "Usuario o contraseña incorrectos." : msgError(error);
    return;
  }
  await iniciarSesion();
}
async function iniciarSesion() {
  UI.cargando = true; render();
  try {
    if (!(await cargarPerfil())) { await sb.auth.signOut(); UI.cargando = false; render(); toast("Tu usuario no tiene acceso al sistema.", true); return; }
    if (!YO.debe_cambiar_clave) await cargarDatos();
    UI.cargando = false;
    if (YO.debe_cambiar_clave) { render(); return; }
    abrirDesdeHash(); render();
  } catch (e) { UI.cargando = false; S = null; render(); toast(msgError(e), true); }
}
async function salir() {
  closeModal(); await sb.auth.signOut(); YO = null; S = null; PERMS = []; CONSOLA = null; URLS = {}; UI.view = "inicio"; render();
}
function abrirDesdeHash() {
  const m = (location.hash || "").match(/ACT-\d{6}/i);
  if (m && S) { const x = byCode(m[0]); if (x) { UI.view = "ficha"; UI.arg = x.id; } history.replaceState(null, "", location.pathname + location.search); }
}

let qT;
document.addEventListener("input", e => {
  const t = e.target;
  if (t.dataset.filter === "q") { UI.f.q = t.value; clearTimeout(qT); qT = setTimeout(() => { const pos = t.selectionStart; render(); const n = $("#fq"); if (n) { n.focus(); n.setSelectionRange(pos, pos); } }, 250); }
  if (t.dataset.movf === "q") { UI.movF.q = t.value; clearTimeout(qT); qT = setTimeout(() => { render(); const n = $("#mq"); if (n) { n.focus(); n.setSelectionRange(n.value.length, n.value.length); } }, 250); }
});
document.addEventListener("change", async e => {
  const t = e.target;
  if (t.dataset.filter && t.dataset.filter !== "q") {
    const k = t.dataset.filter; UI.f[k] = t.type === "checkbox" ? t.checked : t.value;
    if (k === "prov") { UI.f.loc = ""; UI.f.base = ""; } if (k === "loc") UI.f.base = "";
    render(); return;
  }
  if (t.dataset.movf) { UI.movF[t.dataset.movf] = t.value; render(); return; }
  if (t.dataset.fotof) { UI.fotoF = t.value; render(); return; }
  if (t.dataset.repsel) { UI.repSel[t.dataset.repsel] = t.value; render(); return; }
  if (t.dataset.cascade) {
    const p = t.dataset.cascade, prov = $("#" + p + "prov").value;
    if (t.name === "prov") { const locs = allLocs(prov); $("#" + p + "loc").innerHTML = locs.map(l => `<option>${esc(l)}</option>`).join(""); }
    const loc = $("#" + p + "loc").value;
    $("#" + p + "base").innerHTML = allBases(prov, loc).map(b => `<option>${esc(b)}</option>`).join("");
    return;
  }
  if (t.dataset.venc && t.value) { const vv = $("#" + t.dataset.venc); if (vv) vv.value = addDays(t.value, 365); return; }
  if (t.dataset.preview && t.files[0]) { const src = await resizeImage(t.files[0], 600); $("#m_prev").innerHTML = `<img src="${src}" alt="Vista previa" style="max-height:220px;border-radius:6px;border:1px solid var(--line)">`; const other = t.id === "m_cam" ? $("#m_file") : $("#m_cam"); if (other) other.value = ""; const er = $("#merr_file"); if (er) er.textContent = ""; return; }
  if (t.dataset.scan && t.files[0]) { scanImage(t.files[0]); t.value = ""; return; }
  if (t.dataset.import && t.files[0]) { parseImport(t.files[0]); return; }
});
document.addEventListener("keydown", e => { if (e.key === "Escape" && $("#modal-root").innerHTML) closeModal(); });
document.addEventListener("click", e => { const tr = e.target.closest("tr[data-open]"); if (tr && !e.target.closest("button")) { /* manejado arriba */ } }, true);

